import requests

def get_social_media_data(url):
    headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/58.3500 Safari/537.36'}
    session = requests.Session()
    response = session.get(url, headers=headers)
    if response.status_code == 200:
        soup = response.content.decode('utf-8')
        links = soup.find_all('a')
        for link in links:
            if 'https://instagram.com/' in link.attrs['href'] or 'https://facebook.com/' in link.attrs['href']:
                print(link.attrs['href'])
            else:
                print('Skipping link: ' + link.attrs['href'])
    else:
        print("Failed to retrieve data. Status code: ", response.status_code)
```
